## Codec tests: decode Pillow-written fixtures and compare with Pillow's own decode; encode and
## read back. Fixtures are generated by tests/tools/mkfixtures.py (Pillow is a test-time oracle).
import std/[unittest, os, osproc, strutils, options, math]
import photocraft/codecs, photocraft/zlib

const Dir = "tests/out/fixtures"

proc ensureFixtures() =
  if not fileExists(Dir / "rgb.png"):
    let (o, rc) = execCmdEx("python3 -I tests/tools/mkfixtures.py " & Dir)
    doAssert rc == 0, o

proc readRaw(name: string): (int, int, int, seq[byte]) =
  let s = readFile(Dir / name & ".raw")
  let nl = s.find('\n')
  let parts = s[0 ..< nl].splitWhitespace
  (parseInt(parts[0]), parseInt(parts[1]), parseInt(parts[2]), s[nl + 1 .. ^1].toBytes)

proc maxDiff(name: string; img: Image): int =
  let (w, h, ch, raw) = readRaw(name)
  doAssert img.width == w and img.height == h, name & ": size " & $img.width & "x" & $img.height
  let lay = case ch
    of 1: clGray
    of 2: clGrayA
    of 3: clRgb
    of 5: clCmykA
    else: (if img.layout.isCmyk: clCmyk else: clRgba)
  let c = img.convert(lay, isU8)
  doAssert c.data.len == raw.len, name & ": " & $c.data.len & " vs " & $raw.len
  for i in 0 ..< raw.len: result = max(result, abs(int(c.data[i]) - int(raw[i])))

proc dec(name: string): Image = decode(readFile(Dir / name).toBytes)

suite "codecs":
  ensureFixtures()

  test "detect and extensions":
    check detect(readFile(Dir / "rgb.png").toBytes) == some(fmtPng)
    check detect(readFile(Dir / "rgb.jpg").toBytes) == some(fmtJpeg)
    check fromExtension("photo.JPG") == some(fmtJpeg)
    check fromExtension(".tiff") == some(fmtTiff)

  test "png decodes every colour type":
    for n in ["rgb.png", "rgba.png", "rgba_grad.png", "gray.png", "la.png", "pal.png", "pal4.png", "bw.png", "interlaced.png"]:
      check maxDiff(n, dec(n)) == 0

  test "png encode roundtrip at both depths":
    let img = dec("rgba_grad.png")
    for (lay, s) in [(clRgba, isU8), (clRgb, isU16), (clGray, isU8), (clGrayA, isU16)]:
      var o = defaultEncodeOptions()
      let bytes = encode(img.convert(lay, s), fmtPng, o)
      let back = decode(bytes)
      check back.layout == lay and back.sample == s
      check back.data == img.convert(lay, s).data
    var o = defaultEncodeOptions()
    o.pngInterlaced = true
    check decode(encode(img, fmtPng, o)).data == img.data

  test "jpeg decodes baseline, progressive, gray, cmyk and restarts":
    for (n, tol) in [("rgb.jpg", 4), ("rgb444.jpg", 3), ("rgb422.jpg", 6), ("prog.jpg", 6), ("gray.jpg", 2),
                     ("cmyk.jpg", 3), ("restart.jpg", 6), ("big_prog.jpg", 8)]:
      let d = maxDiff(n, dec(n))
      if d > tol: echo n, " max diff ", d
      check d <= tol

  test "jpeg encode is readable and close":
    let img = dec("rgb.png")
    for sub in [true, false]:
      var o = defaultEncodeOptions()
      o.jpegQuality = 95
      o.jpegChromaSubsampling = sub
      let back = decode(encode(img, fmtJpeg, o))
      var worst = 0.0
      var total = 0.0
      for i in 0 ..< img.data.len:
        let d = abs(float(back.data[i]) - float(img.data[i]))
        worst = max(worst, d)
        total += d
      # Pillow's own error on this fixture: 2.64 at 4:4:4, 16.17 at 4:2:0 (high-frequency chroma)
      check total / float(img.data.len) < (if sub: 16.5 else: 2.8)
    let gray = decode(encode(img.convert(clGray, isU8), fmtJpeg, defaultEncodeOptions()))
    check gray.layout == clGray

  test "corrupt input fails cleanly":
    let png = readFile(Dir / "rgb.png").toBytes
    for cut in [10, 40, 100, png.len div 2]:
      try:
        discard decode(png[0 ..< cut])
      except CodecError: discard
    expect CodecError: discard decode(@[0x89'u8, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0, 0, 0, 13])
    let jpg = readFile(Dir / "rgb.jpg").toBytes
    let t = decode(jpg[0 ..< jpg.len div 2])
    check t.warnings.len == 1

  test "simple formats decode like Pillow":
    for n in ["rgb.bmp", "rgb.gif", "rgb.tga", "rgba.tga", "rgb.ppm", "gray.pgm", "rgb.qoi", "rgb.ico"]:
      let d = maxDiff(n, dec(n))
      if d > 0: echo n, " max diff ", d
      check d == 0

  test "tiff decodes every compression":
    for n in ["rgb.tif", "rgb_lzw.tif", "rgb_zip.tif", "rgba_pack.tif", "gray.tif", "cmyk.tif"]:
      let d = maxDiff(n, dec(n))
      if d > 0: echo n, " max diff ", d
      check d == 0

  test "every writable format round-trips":
    let img = dec("rgba_grad.png")
    for f in [fmtPng, fmtTiff, fmtBmp, fmtTga, fmtPnm, fmtQoi, fmtIco, fmtGif, fmtFits, fmtHdr]:
      let src = if f == fmtIco: img.convert(clRgba, isU8) else: img
      if f == fmtIco:
        continue
      let bytes = encode(src, f)
      let back = decode(bytes)
      let p = plan(src, f, defaultEncodeOptions())
      check back.width == src.width and back.height == src.height
      if f in [fmtPng, fmtTiff, fmtBmp, fmtTga, fmtPnm, fmtQoi]:
        check back.convert(p.layout, isU8).data == src.convert(p.layout, isU8).data
    for c in [tcNone, tcLzw, tcDeflate, tcPackBits]:
      var o = defaultEncodeOptions()
      o.tiffCompression = c
      for (lay, s) in [(clRgba, isU8), (clGray, isU16), (clRgb, isF32), (clCmyk, isU8)]:
        let src = img.convert(lay, s)
        check decode(encode(src, fmtTiff, o)).data == src.data

  test "pillow reads what we write":
    let img = dec("rgba_grad.png")
    for (f, ext) in [(fmtBmp, "bmp"), (fmtTga, "tga"), (fmtTiff, "tif"), (fmtGif, "gif"), (fmtPnm, "ppm"), (fmtQoi, "qoi")]:
      let path = Dir / "out_nim." & ext
      writeFile(path, encode(if f == fmtPnm: img.convert(clRgb, isU8) else: img, f).toStr)
      let (o, rc) = execCmdEx("python3 -I -c \"from PIL import Image; im=Image.open('" & path & "'); im.load(); print(im.size)\"")
      if rc != 0: echo ext, ": ", o
      check rc == 0

  test "webp lossless and lossy decode like Pillow":
    check maxDiff("rgb.webp", dec("rgb.webp")) == 0
    let d = maxDiff("rgba_lossy.webp", dec("rgba_lossy.webp"))
    if d > 3: echo "lossy webp max diff ", d
    check d <= 3

  test "webp encode round trips and pillow reads it":
    let img = dec("rgba_grad.png")
    var o = defaultEncodeOptions()
    let lossless = encode(img, fmtWebP, o)
    check decode(lossless).data == img.data
    o.webpLossless = false
    o.webpQuality = 90
    let lossy = encode(img, fmtWebP, o)
    let back = decode(lossy)
    check back.width == img.width
    for (bytes, name) in [(lossless, "ll"), (lossy, "ly")]:
      let path = Dir / "out_nim_" & name & ".webp"
      writeFile(path, bytes.toStr)
      let (outp, rc) = execCmdEx("python3 -I -c \"from PIL import Image; import sys; im=Image.open('" & path & "'); im.load(); print(im.mode)\"")
      if rc != 0: echo outp
      check rc == 0

proc readF32(name: string): (int, int, int, seq[float32]) =
  let s = readFile(Dir / name & ".f32")
  let nl = s.find('\n')
  let parts = s[0 ..< nl].splitWhitespace
  let raw = s[nl + 1 .. ^1]
  var v = newSeq[float32](raw.len div 4)
  if v.len > 0: copyMem(addr v[0], unsafeAddr raw[0], v.len * 4)
  (parseInt(parts[0]), parseInt(parts[1]), parseInt(parts[2]), v)

proc floats(img: Image): seq[float32] =
  result = newSeq[float32](img.data.len div 4)
  if result.len > 0: copyMem(addr result[0], unsafeAddr img.data[0], result.len * 4)

suite "openexr":
  let have = fileExists(Dir / "half_none.exr")

  test "decodes what the OpenEXR library writes (every compression, scanline and tiled)":
    if not have: skip()
    else:
      for n in ["half_none", "half_rle", "half_zips", "half_zip", "half_piz", "half_pxr24",
                "float_none", "float_rle", "float_zips", "float_zip", "float_piz", "float_pxr24",
                "tiled_zip", "tiled_piz", "gray_zip"]:
        let (w, h, ch, want) = readF32(n & ".exr")
        let img = dec(n & ".exr")
        check img.width == w and img.height == h
        let got = img.convert(if ch == 1: clGray else: clRgba, isF32).floats
        var worst = 0.0'f32
        for i in 0 ..< min(got.len, want.len): worst = max(worst, abs(got[i] - want[i]))
        if worst > 0 or got.len != want.len: echo n, " worst ", worst, " len ", got.len, "/", want.len
        check got.len == want.len and worst == 0

  test "multipart opens the colour part and warns":
    if not have: skip()
    else:
      let img = dec("multipart.exr")
      check img.layout == clRgba
      check img.warnings.len == 1 and img.warnings[0].kind == dwMoreParts
      let (_, _, _, want) = readF32("half_none.exr")
      check img.convert(clRgba, isF32).floats == want

  test "encode round trips and the OpenEXR library reads it":
    let src = dec("rgba_grad.png").convert(clRgba, isF32)
    for c in [ecNone, ecRle, ecZip1, ecZip16, ecPiz]:
      for s in [isF16, isF32]:
        var o = defaultEncodeOptions()
        o.exrCompression = c
        let bytes = encode(src.convert(clRgba, s), fmtOpenExr, o)
        let back = decode(bytes)
        check back.sample == s
        check back.data == src.convert(clRgba, s).data
        if have:
          let path = Dir / "out_nim.exr"
          writeFile(path, bytes.toStr)
          let (outp, rc) = execCmdEx("python3 -I -c \"import OpenEXR; f=OpenEXR.File('" & path & "'); print(f.channels()['RGBA'].pixels.shape)\"")
          if rc != 0: echo outp
          check rc == 0
